@Component("alert-handler")
@ProcessingGroup("alert-processing-group")
public class AlertEventHandler {
	
	// core constructor
	AlertEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAlertEvent
     */
    @EventHandler
    public void handle( CreateAlertEvent event) {
        entityManager.persist(new Alert(event.getAlertId(), event.getTitle(), event.getCreatedAt(), event.getMetric(), event.getDashboard(), event.getDataset(), event.getRule(), event.getAnomalies(), event.getSubscribers(), event.getSeverity(), event.getStatus()));
    }

    /*
     * @param	event UpdateAlertEvent
     */
    @EventHandler
    public Alert handle( UpdateAlertEvent event) {
    	entityManager.merge(new Alert(event.getAlertId(), event.getTitle(), event.getCreatedAt(), event.getMetric(), event.getDashboard(), event.getDataset(), event.getRule(), event.getAnomalies(), event.getSubscribers(), event.getSeverity(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteAlertEvent
     */
    @EventHandler
    public void on( DeleteAlertEvent event) {
    	Alert entity = new Alert();
   
    	// ------------------------------------------
    	// apply the AlertId
    	// ------------------------------------------
    	entity.setAlertId( event.getAlertId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AlertRepository alertEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AlertEventHandler.class.getName());

}
